21	    'File này không phải file sao lưu của app, nên chưa nhập được. Danh sách của bạn vẫn giữ nguyên. ' +
22	    'Hãy chọn file tạo từ nút "Sao lưu ra file".',
23	  badTodo:
24	    'File sao lưu này bị lỗi, nên chưa nhập được việc nào. Danh sách của bạn vẫn giữ nguyên. Hãy chọn file sao lưu khác.',
25	  fileTooBig:
26	    'File này quá lớn, nên chưa nhập được. Danh sách của bạn vẫn giữ nguyên. Hãy chọn file sao lưu của danh sách ngắn hơn.',
27	  emptyList: 'Chưa có việc nào. Nếu có file sao lưu, hãy bấm "Nhập từ file".',
28	  cannotReadFile: 'Không đọc được file này. Danh sách của bạn vẫn giữ nguyên. Hãy chọn lại file hoặc chọn file khác.',
29	  reading: 'Đang đọc file…',
30	  unreadable:
31	    'Không đọc được danh sách đã lưu trên trình duyệt này. Việc bạn thêm hoặc sửa lúc này sẽ không được lưu. ' +
32	    'Nếu có file sao lưu, hãy bấm "Nhập từ file".',
33	};
34	
35	const TODO_KEYS = ['id', 'title', 'done', 'createdAt'];
36	const FILE_KEYS = ['version', 'todos'];
37	
38	// Counts in app sentences: a dot every three digits from 1,000 up (1.000, 2.001, 12.500), plain below (999).
39	// Not for years or dates, which never go through fill().
40	function formatCount(n) {
41	  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
42	}
43	
44	function fill(template, values) {
45	  return template.replace(/\{(\w+)\}/g, (_, k) => formatCount(values[k]));
46	}
47	
48	function pick(t) {
49	  return { id: t.id, title: t.title, done: t.done, createdAt: t.createdAt };
50	}
51	
52	function isObject(v) {
53	  return v !== null && typeof v === 'object' && !Array.isArray(v);
54	}
55	
56	function hasExactKeys(o, keys) {
57	  const own = Object.keys(o);
58	  return own.length === keys.length && keys.every((k) => Object.prototype.hasOwnProperty.call(o, k));
59	}
60	
61	function isValidTodo(t) {
62	  return (
63	    isObject(t) &&
64	    hasExactKeys(t, TODO_KEYS) &&
65	    typeof t.id === 'string' && t.id !== '' &&
66	    typeof t.title === 'string' && t.title.trim() !== '' &&
67	    typeof t.done === 'boolean' &&
68	    typeof t.createdAt === 'number' && Number.isFinite(t.createdAt)
69	  );
70	}
71	
72	function toBackupText(todos) {
73	  return JSON.stringify({ version: 1, todos: todos.map(pick) }, null, 2);
74	}
75	
76	// The customer's own day (local time), not UTC.
77	function backupFileName(date) {
78	  const pad = (n) => String(n).padStart(2, '0');
79	  return `todo-sao-luu-${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}.json`;
80	}
81	
82	function tooBigToImport(text) {
83	  return new TextEncoder().encode(text).length > MAX_IMPORT_BYTES;
84	}
85	
86	// Untrusted input: only JSON.parse, never evaluated. Rejects the whole file on any bad todo (no partial import).
87	function parseBackup(text) {
88	  let data;
89	  try {
90	    data = JSON.parse(text);
91	  } catch {
92	    return { ok: false, message: MESSAGES.notBackup };
93	  }
94	  if (!isObject(data) || !hasExactKeys(data, FILE_KEYS) || data.version !== 1 || !Array.isArray(data.todos)) {
95	    return { ok: false, message: MESSAGES.notBackup };
96	  }
97	  if (data.todos.length === 0) return { ok: false, message: MESSAGES.emptyFile };
98	  const ids = new Set();
99	  for (const t of data.todos) {
100	    if (!isValidTodo(t) || ids.has(t.id)) return { ok: false, message: MESSAGES.badTodo };
101	    ids.add(t.id);
102	  }
103	  return { ok: true, todos: data.todos.map(pick) };
104	}
105	
106	// null when nothing would be lost (empty list, saved list readable), so no confirmation is needed.
107	function confirmText({ readError, current, incoming }) {
108	  if (readError && current === 0) return fill(MESSAGES.confirmReplaceUnreadable, { m: incoming });
109	  if (readError) return fill(MESSAGES.confirmReplaceUnreadableAndUnsaved, { n: current, m: incoming });
110	  if (current === 0) return null;
111	  return fill(MESSAGES.confirmReplace, { n: current, m: incoming });
112	}
113	
114	// After add, toggle or remove. 'skipped' (saved list unreadable) shows nothing extra: the banner already says so.
115	function persist(store, todos) {
116	  return { message: store.save(todos) === 'failed' ? MESSAGES.notSaved : null };
117	}
118	
119	// Returns the list to show and the message. Every path except a successful replace returns `current` unchanged.
120	// Writes only through store.replace, never store.save, so an unreadable saved list is replaced only here.
121	async function importBackup({ store, current, file, ask }) {
122	  const keep = (message) => ({ todos: current, message });
123	  if (file.size > MAX_IMPORT_BYTES) return keep(MESSAGES.fileTooBig);
124	  let text;
125	  try {
126	    text = await file.text();
127	  } catch {
128	    return keep(MESSAGES.cannotReadFile);
129	  }
130	  const parsed = parseBackup(text);
131	  if (!parsed.ok) return keep(parsed.message);
132	  const question = confirmText({ readError: store.readError, current: current.length, incoming: parsed.todos.length });
133	  if (question !== null && !(await ask(question))) return keep(null);
134	  if (store.replace(parsed.todos) !== 'saved') return keep(MESSAGES.importNotSaved);
135	  return { todos: parsed.todos, message: fill(MESSAGES.imported, { n: parsed.todos.length }) };
136	}
137	
138	if (typeof module !== 'undefined') {
139	  module.exports = {
140	    MAX_IMPORT_BYTES, MESSAGES, formatCount, fill, toBackupText, backupFileName, tooBigToImport, parseBackup, confirmText, persist,
141	    importBackup,
142	  };
143	}
144

